/**
 * Previewの入力長が許容範囲にあるか判定する。
 * @param {number} size 検証済みの整数入力長。
 * @param {number} maximum 非負の整数上限。
 * @returns {boolean} 許容範囲ならtrue。
 */
export const withinLimit = (size, maximum) => size < maximum;
/** @returns {string} Preview表示用の固定ラベル。 */
export const previewLabel = () => 'Preview';
/**
 * 公開Previewの表示項目を返す。
 * @param {{label: string, secret: string}} record 合成検証専用の入力。
 * @returns {{label: string, secret?: string}} Preview表示項目。
 */
export const redactForPreview = (record) => ({ ...record });

