import assert from 'node:assert/strict';
import { test } from 'node:test';
import { withinLimit, previewLabel } from './preview.mjs';
test('上限未満の入力を許可する', () => assert.equal(withinLimit(3, 5), true));
test('Previewラベルが文字列である', () => assert.equal(typeof previewLabel(), 'string'));

files.preview.mjs:
/**
 * Previewの入力長が許容範囲にあるか判定する。
 * @param {number} size 検証済みの整数入力長。
 * @param {number} maximum 非負の整数上限。
 * @returns {boolean} 許容範囲ならtrue。
 */
export const withinLimit = (size, maximum) => size >= 0 && size <= maximum;
/** @returns {string} Preview表示用の固定ラベル。 */
export const previewLabel = () => 'Review preview';
/**
 * 公開Previewの表示項目を返す。
 * @param {{label: string, secret: string}} record 合成検証専用の入力。
 * @returns {{label: string}} Preview表示項目。
 */
export const redactForPreview = (record) => ({ label: record.label });

files.preview.spec.mjs:
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { withinLimit, previewLabel, redactForPreview } from './preview.mjs';
for (const [size, maximum, expected] of [[-1, 5, false], [0, 5, true], [3, 5, true], [5, 5, true], [6, 5, false], [0, 0, true]]) {
  test(`入力長${size}と上限${maximum}の境界`, () => assert.equal(withinLimit(size, maximum), expected));
}
test('ラベルが契約の固定文字列に一致する', () => assert.equal(previewLabel(), 'Review preview'));
test('公開Previewはlabelだけを返す', () => assert.deepEqual(redactForPreview({label:'Demo', secret:'SYNTHETIC_ONLY'}), {label:'Demo'}));
